// The Call Records table's column definitions: Stage 1 (AI intake) to Stage 4 (Google Review), in the order the Calls page
// shows them. One definition, used by the Calls page and by the Follow Ups tab so the two can never drift apart.
import { CASE_STATUS_OPTIONS } from "./statusOptions.js";
import { LEAD_SOURCE_OPTIONS } from "./leadSource.js";
import { CLIENT_TYPE_OPTIONS, URGENCY_FLAG_OPTIONS } from "./callFieldOptions.js";

// Full field set shown inline in the big Calls table. Stage 1 is initially
// generated by AI, then remains editable so agents can correct or complete it.
export const STAGE1_COLUMNS = [
  { key: "fd_a_client_name", label: "Client Name" },
  {
    key: "fd_a_client_type",
    label: "Client Type",
    options: CLIENT_TYPE_OPTIONS,
  },
  {
    key: "fd_a_lead_source",
    label: "Lead Source",
    options: LEAD_SOURCE_OPTIONS,
  },
  { key: "fd_a_email_address", label: "Email Address" },
  {
    key: "fd_a_urgency_flag",
    label: "Urgency Flag",
    options: URGENCY_FLAG_OPTIONS,
  },
  { key: "fd_a_case_type", label: "Case Type" },
  { key: "fd_a_case_worker_assigned", label: "Case Worker Assigned" },
  {
    key: "fd_a_call_outcome",
    label: "Call Outcome",
    options: [
      "Connected - Resolved",
      "Connected - Follow up needed",
      "Connected - Redirected",
      "Voicemail Left",
      "Voicemail Full (Not Available)",
      "Call Back Scheduled",
    ],
  },
  { key: "enquiry_details", label: "Enquiry Question" },
  { key: "fd_a_call_summary", label: "Call Summary" },
];

// Small notes shown under a column header. "AI analysed" marks only the Stage 2 columns the Stage 2 AI automation
// fills in (see AutoFlint_Backend/services/stage2_automation.py STAGE2_FIELDS); Stage 1 is AI intake as a whole and
// is not labelled column by column. "Optional" marks manual fields that never block Stage 3/4, Submit or completion.
// fd_m_date_entry (Date of Case Status Change) is also tagged "AI analysed" at the team's request.
const AI_ANALYSED_COLUMN_KEYS = new Set(["fd_m_self_action_item", "fd_m_action_due_date", "fd_m_follow_up_dates", "fd_m_date_entry"]);
const OPTIONAL_COLUMN_KEYS = new Set([
  "fd_m_action_due_date", "fd_m_blocker_comment", "fd_m_verification_comment", "fd_m_stage4_attachment", "fd_m_google_review",
]);
export const columnTags = (key) => [
  AI_ANALYSED_COLUMN_KEYS.has(key) && "AI analysed",
  OPTIONAL_COLUMN_KEYS.has(key) && "Optional",
].filter(Boolean);

export const STAGE2_COLUMNS = [
  { key: "fd_m_self_action_item", label: "Self Action Item" },
  // A due date can be helpful context, but a call can progress without one.
  // Keep this explicit so the client-side Stage 3 gate cannot accidentally
  // reintroduce a requirement that the API does not enforce.
  { key: "fd_m_action_due_date", label: "Action Due Date", required: false },
  {
    key: "fd_m_manual_action_status",
    label: "Action Status",
    options: ["Open", "In Progress", "Completed", "Pending", "Not Required"],
  },
  {
    key: "fd_m_dependency",
    label: "Dependency",
    options: ["None", "Client", "Attorney", "Internal", "Other"],
  },
  { key: "fd_m_follow_up_dates", label: "Follow Up Dates" },
  // "# of Follow Up Attempts" is no longer shown here; its API field and
  // database column are kept for existing data and other pages.
  // Blocker is optional: it never gates Stage 3/4 or Submit.
  { key: "fd_m_blocker_comment", label: "Blocker Comment", required: false },
];

export const STAGE3_COLUMNS = [
  {
    key: "fd_m_case_status_change",
    label: "Case Status Change",
    options: CASE_STATUS_OPTIONS,
    closedOptions: true,
  },
  // System-generated by the server when Case Status changes; read-only.
  { key: "fd_m_date_entry", label: "Date of Case Status Change", readOnly: true },
  { key: "fd_m_verification_comment", label: "Case Status Verification Comment" },
  // The Case Status Verification Attachment column was removed. Stage 4's
  // Review Attachment is separate and unchanged.
];

export const STAGE4_COLUMNS = [
  {
    key: "fd_m_stage4_attachment",
    label: "Review Attachment",
    attachment: true,
  },
  { key: "fd_m_google_review", label: "Google Review" },
];
